module eris_sabotage #(\n    parameter N_MAX = 4,\n    parameter BITS = 4\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [1:0] n,\n    input wire [BITS-1:0] arr_0,\n    input wire [BITS-1:0] arr_1,\n    input wire [BITS-1:0] arr_2,\n    input wire [BITS-1:0] arr_3,\n    output reg [BITS-1:0] result_0,\n    output reg [BITS-1:0] result_1,\n    output reg [BITS-1:0] result_2,\n    output reg [BITS-1:0] result_3,\n    output reg done,\n    output reg impossible\n);\n    // State definitions\n    localparam [1:0] IDLE = 2'b00;\n    localparam [1:0] SEARCH = 2'b01;\n    localparam [1:0] DONE = 2'b10;\n\n    // Input storage\n    reg [1:0] n_reg;\n    reg [BITS-1:0] orig_0;\n    reg [BITS-1:0] orig_1;\n    reg [BITS-1:0] orig_2;\n    reg [BITS-1:0] orig_3;\n\n    // State machine registers\n    reg [1:0] state;\n    reg [1:0] i_reg;\n    reg [1:0] bit_reg;\n    reg found;\n    reg [BITS-1:0] res_0, res_1, res_2, res_3;\n\n    // Candidate generation\n    wire [BITS-1:0] candidate_0 = (i_reg == 0) ? (orig_0 ^ (BITS'(1) << bit_reg)) : orig_0;\n    wire [BITS-1:0] candidate_1 = (i_reg == 1) ? (orig_1 ^ (BITS'(1) << bit_reg)) : orig_1;\n    wire [BITS-1:0] candidate_2 = (i_reg == 2) ? (orig_2 ^ (BITS'(1) << bit_reg)) : orig_2;\n    wire [BITS-1:0] candidate_3 = (i_reg == 3) ? (orig_3 ^ (BITS'(1) << bit_reg)) : orig_3;\n\n    // Sorted check\n    wire sorted = (n_reg <= 1) ? 1'b1 :\n                 (n_reg == 2) ? (candidate_0 <= candidate_1) :\n                 (n_reg == 3) ? (candidate_0 <= candidate_1) && (candidate_1 <= candidate_2) :\n                                 (candidate_0 <= candidate_1) && (candidate_1 <= candidate_2) && (candidate_2 <= candidate_3);\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            impossible <= 1'b0;\n            n_reg <= 2'b0;\n            orig_0 <= {BITS{1'b0}};\n            orig_1 <= {BITS{1'b0}};\n            orig_2 <= {BITS{1'b0}};\n            orig_3 <= {BITS{1'b0}};\n            i_reg <= 2'b0;\n            bit_reg <= 2'b0;\n            found <= 1'b0;\n            res_0 <= {BITS{1'b0}};\n            res_1 <= {BITS{1'b0}};\n            res_2 <= {BITS{1'b0}};\n            res_3 <= {BITS{1'b0}};\n            result_0 <= {BITS{1'b0}};\n            result_1 <= {BITS{1'b0}};\n            result_2 <= {BITS{1'b0}};\n            result_3 <= {BITS{1'b0}};\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    impossible <= 1'b0;\n                    if (start) begin\n                        n_reg <= n;\n                        orig_0 <= arr_0;\n                        orig_1 <= arr_1;\n                        orig_2 <= arr_2;\n                        orig_3 <= arr_3;\n                        i_reg <= 2'b0;\n                        bit_reg <= 2'b0;\n                        found <= 1'b0;\n                        state <= SEARCH;\n                    end\n                end\n\n                SEARCH: begin\n                    if (sorted) begin\n                        found <= 1'b1;\n                        res_0 <= candidate_0;\n                        res_1 <= candidate_1;\n                        res_2 <= candidate_2;\n                        res_3 <= candidate_3;\n                        state <= DONE;\n                    end else begin\n                        if (bit_reg < (BITS-1)) begin\n                            bit_reg <= bit_reg + 2'b1;\n                        end else begin\n                            bit_reg <= 2'b0;\n                            if (i_reg < (n_reg - 2'b1)) begin\n                                i_reg <= i_reg + 2'b1;\n                            end else begin\n                                found <= 1'b0;\n                                state <= DONE;\n                            end\n                        end\n                    end\n                end\n\n                DONE: begin\n                    done <= 1'b1;\n                    if (found) begin\n                        result_0 <= res_0;\n                        result_1 <= res_1;\n                        result_2 <= res_2;\n                        result_3 <= res_3;\n                        impossible <= 1'b0;\n                    end else begin\n                        result_0 <= orig_0;\n                        result_1 <= orig_1;\n                        result_2 <= orig_2;\n                        result_3 <= orig_3;\n                        impossible <= 1'b1;\n                    end\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule